// C++ - naive O(n^2) Z array construction
vector<int> zFunctionNaive(const string& s) {
    int n = (int)s.size();
    vector<int> z(n, 0);

    for (int i = 1; i < n; i++) {
        int k = 0;
        while (i + k < n && s[k] == s[i + k]) {
            k++;
        }
        z[i] = k;
    }
    return z;
}

// C++ - Z array construction in O(n)
vector<int> zFunction(const string& s) {
    int n = (int)s.size();
    vector<int> z(n, 0);
    int l = 0, r = 0;               // [l, r) is the window of the furthest match found so far

    for (int i = 1; i < n; i++) {
        if (i < r) {
            z[i] = min(r - i, z[i - l]);
        }
        while (i + z[i] < n && s[z[i]] == s[i + z[i]]) {
            z[i]++;
        }
        if (i + z[i] > r) {
            l = i;
            r = i + z[i];
        }
    }
    return z;
}

// C++ - pattern matching using the Z array
vector<int> searchPattern(const string& pattern, const string& text) {
    string combined = pattern + "#" + text;   // '#' must not occur in pattern or text
    vector<int> z = zFunction(combined);

    int patLen = (int)pattern.size();
    vector<int> matches;

    for (int i = patLen + 1; i < (int)combined.size(); i++) {
        if (z[i] == patLen) {
            matches.push_back(i - patLen - 1);   // index of the match in the original text
        }
    }
    return matches;
}
